import{_ as o,c as r,o as d,a2 as n}from"./chunks/framework.CHomSxuB.js";const q=JSON.parse('{"title":"3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/3-连板接力与情绪闸门.md","filePath":"A股量化验证/3-连板接力与情绪闸门.md"}'),a={name:"A股量化验证/3-连板接力与情绪闸门.md"};function e(s,t,g,h,l,u){return d(),r("div",null,t[0]||(t[0]=[n('<h1 id="_3-连板接力与情绪闸门-抛硬币与择时幻觉-step-5-v0-5" tabindex="-1">3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5） <a class="header-anchor" href="#_3-连板接力与情绪闸门-抛硬币与择时幻觉-step-5-v0-5" aria-label="Permalink to &quot;3. 连板接力与情绪闸门：抛硬币与择时幻觉（Step 5 / V0.5）&quot;">​</a></h1><blockquote><p>两连发证伪： ① 连板接力本身（2进3 / 3进4 无差别）≈ <strong>抛硬币</strong> —— <code>NO_EDGE</code> ② &quot;情绪温度计&quot;择时（退潮期提前规避）<strong>无单调性</strong> —— <code>GATE_NO_EDGE</code> 卷宗：<code>bench-step5-20260819</code>（基线+闸门）+ <code>v0.5_sentiment_gate_prereg.md</code></p></blockquote><h2 id="第一发-连板接力基线-step-5" tabindex="-1">第一发：连板接力基线（Step 5） <a class="header-anchor" href="#第一发-连板接力基线-step-5" aria-label="Permalink to &quot;第一发：连板接力基线（Step 5）&quot;">​</a></h2><h3 id="故事" tabindex="-1">故事 <a class="header-anchor" href="#故事" aria-label="Permalink to &quot;故事&quot;">​</a></h3><p>&quot;连板股有连板基因，2 进 3、3 进 4 自带正期望&quot;——打板圈最流行的信仰之一。</p><h3 id="实测-243-交易日-成分池-1-324-只" tabindex="-1">实测（243 交易日，成分池 1,324 只） <a class="header-anchor" href="#实测-243-交易日-成分池-1-324-只" aria-label="Permalink to &quot;实测（243 交易日，成分池 1,324 只）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>晋级</th><th>n</th><th>Ev(Close)</th><th>p</th><th>尾部</th></tr></thead><tbody><tr><td>2进3</td><td>2,120</td><td>+0.83%</td><td>0.5045</td><td>—</td></tr><tr><td>3进4</td><td>791</td><td>+0.85%</td><td>0.5033</td><td>p10 = <strong>−10.2%</strong></td></tr></tbody></table><p>期望值看似为正（+0.8%），但 bootstrap p≈0.50——<strong>与抛硬币无统计差异</strong>，即 &quot;+0.83% 是幸存者平均，真实分布是 iid 噪声&quot;，且 3进4 尾部 p10 = −10.2% 说明 <strong>下行尾部极险</strong>（核按钮）。</p><h3 id="裁决-no-edge" tabindex="-1">裁决：<code>NO_EDGE</code> <a class="header-anchor" href="#裁决-no-edge" aria-label="Permalink to &quot;裁决：`NO_EDGE`&quot;">​</a></h3><p>连板晋级不产生&quot;可辨识的正期望&quot;；看到的正均值来自分布右偏，不是可持续 edge。 <strong>负偏态 + 高方差 + iid</strong> —— 教科书式的&quot;赌徒幻觉&quot;结构。</p><h2 id="第二发-情绪闸门-v0-5-预注册证伪系列" tabindex="-1">第二发：情绪闸门（V0.5，预注册证伪系列） <a class="header-anchor" href="#第二发-情绪闸门-v0-5-预注册证伪系列" aria-label="Permalink to &quot;第二发：情绪闸门（V0.5，预注册证伪系列）&quot;">​</a></h2><h3 id="故事-1" tabindex="-1">故事 <a class="header-anchor" href="#故事-1" aria-label="Permalink to &quot;故事&quot;">​</a></h3><p>既然接力 Ev 是噪声，那是不是&quot;退潮期不做、亢奋期才做&quot;就能截住尾部？ V0.5 构造<strong>昨日连板溢价指数 S_T</strong>（昨日连板群体今天的赚钱效应）当 regime 闸门： S_T 冷 → 回避接力；S_T 热 → 参与接力。</p><h3 id="实测-242-天-s-t-覆盖-置换检验" tabindex="-1">实测（242 天 S_T 覆盖，置换检验） <a class="header-anchor" href="#实测-242-天-s-t-覆盖-置换检验" aria-label="Permalink to &quot;实测（242 天 S_T 覆盖，置换检验）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>假设</th><th>门槛</th><th>实测</th><th>结果</th></tr></thead><tbody><tr><td>H1 周期分离度</td><td>ΔEv &gt; +3.00% 且 p &lt; 0.01</td><td>ΔEv = <strong>+0.26%</strong>，置换 p = <strong>0.6975</strong></td><td>❌</td></tr><tr><td>H2 / H3（冷热区接力 vs 全体）</td><td>单调性</td><td><strong>无单调结构</strong></td><td>❌</td></tr></tbody></table><ul><li>十分位诊断：把 S_T 分十档看接力 Ev——<strong>没有任何档位能稳定分离</strong>；</li><li>连续相关性：r≈0.03（p=0.27）——昨日赚钱效应<strong>对次日接力毫无预测力</strong>；</li><li>阈值锚点有误不是主因（即使重选锚点，无单调性意味着不存在能切出区分度的点）。</li></ul><h3 id="裁决-gate-no-edge" tabindex="-1">裁决：<code>GATE_NO_EDGE</code> <a class="header-anchor" href="#裁决-gate-no-edge" aria-label="Permalink to &quot;裁决：`GATE_NO_EDGE`&quot;">​</a></h3><p><strong>连板溢价不存在日间序列相关性</strong>——&quot;情绪温度计&quot;是叙事，不是变量。 任何&quot;换成分位数锚点再试一次&quot;的想法都是 Data Snooping 入口，协议规定：<strong>记录并封存，不得调参重试</strong>。</p><h3 id="更深一层的推论-本轮最有价值的产出" tabindex="-1">更深一层的推论（本轮最有价值的产出） <a class="header-anchor" href="#更深一层的推论-本轮最有价值的产出" aria-label="Permalink to &quot;更深一层的推论（本轮最有价值的产出）&quot;">​</a></h3><blockquote><p>昨日连板群体的赚钱效应，对次日接力的收益分布没有预测力。 短线情绪在日频上<strong>不存在可被统计利用的惯性</strong>——这直接宣判了一大类 &quot;情绪周期择时&quot;策略的死刑，省下未来无数调参时间。</p></blockquote><hr><h2 id="第三发-涨停数量会说谎——封板时段分层-2026-11-04-建立-读盘口径" tabindex="-1">第三发：涨停数量会说谎——封板时段分层（2026-11-04 建立，读盘口径） <a class="header-anchor" href="#第三发-涨停数量会说谎——封板时段分层-2026-11-04-建立-读盘口径" aria-label="Permalink to &quot;第三发：涨停数量会说谎——封板时段分层（2026-11-04 建立，读盘口径）&quot;">​</a></h2><p>上面两发是<strong>统计判决</strong>（<code>NO_EDGE</code> / <code>GATE_NO_EDGE</code>），本节不是——它是一条<strong>读盘口径</strong>， 用来回答一个更朴素的问题：<strong>&quot;今天涨停 116 只&quot;这句话，到底该怎么读？</strong></p><p>起因是 11-03 ~ 11-06 四个交易日，涨停数量给出了三个互相矛盾的信号。</p><table tabindex="0"><thead><tr><th>交易日</th><th>涨停数变化</th><th>指数</th><th>昨日涨停池当日表现</th><th>该怎么读</th></tr></thead><tbody><tr><td>11-03</td><td>125 → <strong>48（−61.6%）</strong></td><td>四线单边下杀（创业板 −2.73%）</td><td>均值 +0.94% / 中位 +0.13% / 上涨 50.4% / <strong>零跌停</strong> / 续板率 12.0%</td><td><strong>缩量退潮，不是崩塌</strong></td></tr><tr><td>11-04</td><td>48 → <strong>116（+141.7%）</strong></td><td>四线 V 型反转（上证 +2.16% 收全天最高）</td><td><strong>中位 −2.34%</strong> / <strong>5 只跌停</strong> / 续板率 25.0%</td><td><strong>指数暴涨，但题材接力背离</strong></td></tr><tr><td>11-05</td><td>116 → <strong>83</strong></td><td>指数走弱</td><td><strong>均值 +4.42% / 中位 +4.26% / 上涨 81.9% / 涨停 23</strong></td><td><strong>老池整体兑现，但续板率仅 18.1%</strong></td></tr><tr><td>11-06</td><td>83 → <strong>32（−61.4%）</strong></td><td>四线全崩（创业板 −3.23%）</td><td>中位 −1.79% / 续板率 13.3%</td><td><strong>真退潮</strong></td></tr></tbody></table><p><strong>11-04 是这条口径的诞生现场</strong>：涨停数一天翻倍多、四大指数 V 型反转、上证收在全天最高点—— 任何一个只看&quot;涨停数 + 指数&quot;的人都会读成&quot;情绪高潮&quot;。但同日<strong>昨日那 116 只的中位数是 −2.34%、还有 5 只跌停</strong>。 <strong>指数在涨、新钱在另起炉灶、老题材在失血</strong>——这三件事同时成立，而&quot;涨停 116 只&quot;一个数字把它们全盖住了。</p><h3 id="口径-按封板时段分桶-看封单质量" tabindex="-1">口径：按封板时段分桶，看封单质量 <a class="header-anchor" href="#口径-按封板时段分桶-看封单质量" aria-label="Permalink to &quot;口径：按封板时段分桶，看封单质量&quot;">​</a></h3><p>做法很简单：把当日全部涨停股按<strong>首次封板时间</strong>分成五桶，各桶统计<strong>封单比中位数</strong>与<strong>流通市值中位数</strong>。</p><table tabindex="0"><thead><tr><th>封板时段</th><th>封单比中位</th><th>流通市值中位（相对）</th><th>性质</th></tr></thead><tbody><tr><td>集合竞价</td><td>2.50%</td><td>最薄</td><td>隔夜一致预期，最强</td></tr><tr><td>早盘（&lt;10:00）</td><td>0.83%</td><td>1×</td><td><strong>主动做多主力</strong></td></tr><tr><td>上午（10:00–11:30）</td><td>0.60%</td><td>1.3×</td><td>主动性次之</td></tr><tr><td>午后前段（13:00–13:30）</td><td>1.09%</td><td>1.0×</td><td>参差</td></tr><tr><td><strong>尾盘（13:30 后）</strong></td><td><strong>0.25%</strong></td><td><strong>约 4×</strong></td><td><strong>大市值被动补涨，封单极薄</strong></td></tr></tbody></table><p>11-04 的 116 只里，<strong>尾盘封的占 64.7%（75 只）</strong>，且这组的流通市值中位数是早盘组的<strong>约 4 倍</strong>、封单比只有 <strong>0.25%</strong>。 翻译成人话：<strong>不是资金抢筹，是指数逼空时大市值票被&quot;顺手&quot;推到涨停，封单薄得像一层纸。</strong> 真正有接力价值的只有早盘封的那 20 只（17.2%）。</p><p><strong>11-05 给了这个口径一次反向验证</strong>：同一套分层，早盘封板占比从 17.2% 跳到 <strong>50.6%</strong>、尾盘封从 64.7% 掉到 <strong>14.5%</strong>、 封单比中位从 0.34% 升到 <strong>0.73%</strong>。而当天的主线（光伏链 19 只，占 22.9%）在 09:31–09:45 十五分钟内集中封了 9 只， 连板高度载体也在其中。→ <strong>宽度、时间集中度、纵深三者齐备</strong>，这才是&quot;量的真伪&quot;里&quot;真&quot;的那一半。</p><h3 id="沉淀-三个维度必须同时读" tabindex="-1">沉淀：三个维度必须同时读 <a class="header-anchor" href="#沉淀-三个维度必须同时读" aria-label="Permalink to &quot;沉淀：三个维度必须同时读&quot;">​</a></h3><ol><li><strong>数量</strong>（涨停几只）——最容易被单独引用，也最容易骗人；</li><li><strong>昨日池的今日表现</strong>（均值 / 中位 / 上涨占比 / 跌停数）——它测的是&quot;接力资金还在不在&quot;；</li><li><strong>封板时段结构</strong>（各桶封单比中位 + 流通市值中位）——它测的是&quot;这批涨停是谁封的&quot;。</li></ol><blockquote><p><strong>一条纪律：任何&quot;涨停数暴涨 / 腰斩&quot;的判断，都必须同时给出另外两个维度，否则不构成读数。</strong> 11-03 腰斩是缩量退潮（老池还在涨、零跌停），11-06 腰斩是真退潮（老池中位 −1.79%、续板率 13.3%）—— <strong>同一个&quot;腰斩&quot;，两种完全不同的处置</strong>。</p><p>这条口径<strong>不进统计、不改闸门、不影响任何判定</strong>。它只用于读盘与预案撰写， 目的是让&quot;今天的盘面到底强不强&quot;这个判断有可复核的依据，而不是靠&quot;感觉今天涨停挺多&quot;。</p><p>⚠️ 一个实现层面的坑：<strong>首次封板时间是 unix 时间戳（秒），不是字符串</strong>。 直接按字符串比较会把全部记录都判成&quot;13:30 之后&quot;，于是&quot;尾盘封 100%&quot;这种荒谬读数会被当成真实结果—— 而它看起来<strong>完全像一条惊人的发现</strong>。<strong>口径正确的第一道检验，永远是&quot;结果是否荒谬&quot;，而不是&quot;结果是否好看&quot;。</strong></p></blockquote><hr><p><strong>验证线汇总导航</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · <a href="/A股量化验证/2-公告排雷.html">上一线：公告排雷</a> · <a href="/A股量化验证/4-分歧低吸.html">下一线：分歧低吸</a></p>',36)]))}const p=o(a,[["render",e]]);export{q as __pageData,p as default};
